contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: tries to call create and records whether it reverted
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        // no precondition on parameters
        // read the programOperators mapping for msg.sender (which will be this test contract when c methods execute)
        bool wasOperatorBefore = c.programOperators(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        address result;
        c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            // If it didn't revert, try-catch above does not return the value; call again as a view is impossible because create is non-view.
            // Instead we observe that it succeeded (didn't revert).
        }

        // General rule: if the call did not revert then this contract must have been a program operator
        // (i.e., programOperators[this]==true). We assert that property.
        assert(reverted || wasOperatorBefore);
    }

    receive() external payable {}
}

